import {creditCache} from './credit-cache.js';
import {photoPlan,recipeNames,shotChoices,childTryonAllowed} from './photo-recipes.js?v=children-11';
import {photoModelGender,childReferencePath} from './photo-models.js?v=children-11';
import {preparePhoto} from './photo-editor.js?v=fixed-3';
import {createPhotoProgress} from './photo-progress.js?v=children-11';
const titles={cover:'Вещь без модели',front:'Модель спереди',back:'Модель сзади'};
async function request(path,body){let r;try{r=await fetch('/api/photos'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(body?100000:40000),...(body?{body:JSON.stringify(body)}:{})});}catch{throw Error(body?'Соединение прервалось. Запрос мог быть принят — проверьте кабинет FASHN перед повторным запуском.':'Не удалось проверить обработку. Повторите проверку текущего задания.');}const data=await r.json();if(!r.ok){const error=Error(data.message||'Не удалось обработать фото.');error.activeJob=data.activeJob;throw error;}return data;}
const cachedCredits=creditCache(()=>request('/credits'));
let creditOwner='';
export async function refreshPhotoCredits(owner=creditOwner,force=false){
 creditOwner=owner;const hosts=[...document.querySelectorAll('[data-photo-credits]')];if(!hosts.length)return;
 try{const d=await cachedCredits(owner,force);if(owner!==creditOwner)return;
 for(const host of hosts){if(!host.isConnected)continue;host.textContent=`Кредиты магазина: ${d.balance??'нет данных'} · Потрачено ${d.usage.scope==='personal'?'вами':'магазином'}: ${d.usage.confirmed}${d.usage.estimated?' + примерно '+d.usage.estimated:''}${d.usage.unknown?' · Без данных о стоимости: '+d.usage.unknown+' заданий':''}. Расход учтён по заданиям этого сайта.`;}
 }catch{for(const host of hosts)if(host.isConnected)host.textContent='Баланс кредитов временно недоступен.';}
}

export async function draftRequest(path='',body,method='GET'){
 const r=await fetch('/api/photos/drafts'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.message||'Не удалось сохранить черновик.');return data;
}
export async function refreshPhotoDrafts(open){for(const host of document.querySelectorAll('[data-photo-drafts]')){try{const rows=await draftRequest();if(!host.isConnected)continue;host.replaceChildren();if(!rows.length)continue;const title=document.createElement('h3');title.textContent='Черновики';host.append(title);for(const row of rows){const b=document.createElement('button');b.type='button';b.className='btn light';b.textContent=row.name+' · Продолжить';b.onclick=()=>open(row.id);host.append(b);}}catch{host.textContent='Не удалось загрузить черновики.';}}}
function fieldsOf(form){const fields={};for(const el of form.elements){if(!el.name||el.type==='file'||el.name==='photos'||el.name==='modelGender')continue;if(el.type==='checkbox'){if(el.name==='sizes'){if(el.checked)(fields.sizes??=[]).push(el.value);}else fields[el.name]=el.checked;}else fields[el.name]=el.value;}fields.modelGender=form.photoModelGender;return fields;}
function readOriginal(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Оригинальное фото: JPEG, PNG или WebP до 2 МБ, без изменения файла.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Не удалось прочитать фото.'));reader.readAsDataURL(file);});}
export async function bindFixedPhotos(form,product,esc,draft){
 const host=form.querySelector('.photo-editor'),audience=form.querySelector('[name=audience]'),category=form.querySelector('[name=category]');
 let settings={...product?.photoSettings,...draft?.photoSettings},sources={...product?.photoStudio?.sources,...draft?.sources},selected={...product?.photoJobs,...draft?.selected},rows=[...(draft?.jobs||[]),...(product?.photoStudio?.versions||[])],draftId=draft?.id,saveChain=Promise.resolve(),timer,stopped=false,modelChoice=draft?.fields?.modelGender||product?.modelGender||'',busy=new Set(),plan,progress={},status,saveStatus;
 const alive=()=>form.isConnected&&!stopped&&(!form.closest('dialog')||form.closest('dialog').open);
 const gender=()=>{try{return photoModelGender(audience?.value,modelChoice,settings);}catch{return null;}};
 const slotFor=k=>plan.slots.find(s=>s.key===k);
 function compatible(r){const s=slotFor(r.kind);return !!s&&(!r.recipeSignature?plan.settings.recipe==='clothing':r.recipeSignature===plan.signature)&&(!['tryon','wear'].includes(s.mode)||r.modelGender===gender());}
 function ready(k){const s=slotFor(k);return !!s&&!(plan.settings.recipe==='kids'&&plan.needsModel&&!gender())&&!!sources[s.source]&&(!['tryon','wear'].includes(s.mode)||!!gender());}
 function layout(){
 plan=photoPlan(category?.value||'Одежда',audience?.value,settings);settings=plan.settings;form.photoSettings=settings;form.photoModelGender=gender();
 for(const k of Object.keys(selected))if(!slotFor(k))delete selected[k];
 const choices=shotChoices[settings.recipe];
 host.innerHTML=`<h3>Фото: ${esc(plan.name)}</h3><p class="small">Сначала загрузите указанные исходники, затем запустите подготовку. Оригиналы не перерисовываются. Все версии сохраняются в черновике.</p><div class="form-grid">${['Винтаж','Винтажные вещи','Архивные вещи','Редкие вещи','Коллекционные вещи'].includes(category?.value)?`<label>Тип винтажного предмета<select data-setting="itemType">${Object.entries(recipeNames).filter(([k])=>k!=='kids').map(([k,v])=>`<option value="${k}" ${settings.recipe===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}${settings.recipe==='kids'&&childTryonAllowed(category?.value)?`<label>Фотографии<select data-setting="shot"><option value="product" ${settings.shot!=='child'?'selected':''}>Вещь без модели</option><option value="child" ${settings.shot==='child'?'selected':''}>На детской модели · пробный режим</option></select></label><label>Возраст модели<select data-setting="childAge"><option value="">Выберите возраст</option>${['7-9','12-14'].map(age=>`<option value="${age}" ${settings.childAge===age?'selected':''}>${age.replace('-','–')} лет</option>`).join('')}</select></label><label>Детская модель<select data-setting="childGender"><option value="">Выберите модель</option><option value="girl" ${settings.childGender==='girl'?'selected':''}>Девочка</option><option value="boy" ${settings.childGender==='boy'?'selected':''}>Мальчик</option></select></label>`:''}${choices?`<label>Второй кадр<select data-setting="shot">${Object.entries(choices).map(([k,v])=>`<option value="${k}" ${settings.shot===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<label ${plan.slots.every(s=>s.mode==='original')?'hidden':''}>Материал<select data-setting="material">${Object.entries({normal:'Обычный',delicate:'Кружево / прозрачная / тонкая ткань',shiny:'Блеск / пайетки / лак',fur:'Мех'}).map(([k,v])=>`<option value="${k}" ${settings.material===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Дополнительные оригиналы<select data-setting="extraCount">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${settings.extraCount===n?'selected':''}>${n} · всего ${n+3} фото</option>`).join('')}</select></label>${plan.needsModel&&audience?.value==='unisex'?`<label>Модель для унисекс<select data-model-choice><option value="">Выберите модель</option><option value="female" ${modelChoice==='female'?'selected':''}>Женщина</option><option value="male" ${modelChoice==='male'?'selected':''}>Мужчина</option></select></label>`:''}</div><p class="small">Реальные следы износа и дефекты сохраняются. ${settings.recipe==='kids'?'Возраст модели не заменяет размер и ростовку товара. FASHN не гарантирует качество детской примерки; проверьте результат перед публикацией.':plan.needsModel?'Для примерки используется взрослая модель.':''}</p>${settings.recipe==='kids'&&gender()?`<div class="child-model-preview">${['front','back'].map(view=>`<figure><img src="${childReferencePath(settings,view)}" alt="${settings.childGender==='girl'?'Девочка':'Мальчик'} ${settings.childAge} лет · ${view==='front'?'спереди':'сзади'}"><figcaption>${view==='front'?'Спереди':'Сзади'}</figcaption></figure>`).join('')}</div>`:''}<div class="form-grid">${plan.inputs.map(input=>`<label>${esc(input.label)}<input type="file" data-upload="${input.key}" accept="image/jpeg,image/png,image/webp"><span class="small muted">${input.original?'Оригинал без обработки · до 2 МБ':'JPEG, PNG, WebP · до 20 МБ; подготовка размера автоматически'}</span><img data-source-preview="${input.key}" class="fixed-source-preview" hidden alt="Исходное фото"></label>`).join('')}</div><button type="button" class="btn" data-generate-set>Подготовить фотографии</button><div data-batch-progress hidden><progress aria-label="Подготовка фотографий"></progress><span>Обработка… Можно закрыть окно и продолжить из черновика.</span></div><p data-save-status role="status"></p><p data-status role="status"></p><div class="fixed-photo-grid">${plan.slots.map(s=>`<section data-slot="${s.key}"><h4>${esc(s.label)}</h4><p class="small muted">${s.mode==='original'?'Оригинал · без перерисовки':s.mode==='background'?'Очистка фона · без изменения предмета':'ИИ-визуализация'}</p><div data-versions></div>${['tryon','wear','edit'].includes(s.mode)?'<label>Что исправить<textarea data-comment maxlength="500"></textarea></label>':''}<button type="button" data-redo="${s.key}">${s.mode==='original'?'Использовать загруженный оригинал':'Создать ещё версию'}</button><div data-progress></div></section>`).join('')}</div><button type="button" data-refresh>Проверить задания</button>`;
 status=host.querySelector('[data-status]');saveStatus=host.querySelector('[data-save-status]');progress=Object.fromEntries(plan.slots.map(s=>[s.key,createPhotoProgress(host.querySelector(`[data-slot=${s.key}] [data-progress]`),{original:s.mode==='original'})]));draw();
 }
 function draw(){form.photoSettings=settings;form.photoModelGender=gender();for(const input of plan.inputs){const img=host.querySelector(`[data-source-preview=${input.key}]`);img.hidden=!sources[input.key];if(sources[input.key])img.src=sources[input.key];}
 for(const s of plan.slots){const versions=rows.filter(r=>r.kind===s.key&&r.status==='completed'&&compatible(r));if(selected[s.key]&&!versions.some(r=>r.id===selected[s.key]))delete selected[s.key];host.querySelector(`[data-slot=${s.key}] [data-versions]`).innerHTML=versions.map((r,i)=>`<div class="photo-version ${selected[s.key]===r.id?'is-selected':''}"><button type="button" data-zoom="${esc(r.id)}" aria-label="Открыть ${esc(s.label)}, версия ${i+1}"><img class="fixed-photo-result" src="/api/photos/assets/${esc(r.id)}" alt="${esc(s.label)} · версия ${i+1}"></button><button type="button" data-select="${esc(r.id)}" data-kind="${s.key}" aria-pressed="${selected[s.key]===r.id}">${selected[s.key]===r.id?'✓ Выбрано':'Выбрать'} · ${i+1}</button></div>`).join('');}
 form.photoJobs={...selected};form.photoReady=plan.slots.every(s=>selected[s.key]);form.photoImages=form.photoReady?plan.slots.map(s=>'/api/photos/assets/'+selected[s.key]):[];
 const running=busy.size>0;form.dataset.photoBusy=running?'1':'';host.querySelector('[data-batch-progress]').hidden=!running;host.querySelector('[data-generate-set]').disabled=running||!plan.slots.every(s=>ready(s.key));host.querySelectorAll('[data-upload],select').forEach(el=>el.disabled=running);if(audience)audience.disabled=running;form.querySelectorAll('[data-category-parent],[data-category-child]').forEach(el=>el.disabled=running);host.querySelectorAll('[data-redo]').forEach(el=>el.disabled=running||!ready(el.dataset.redo));form.querySelector('[type=submit]').disabled=running||!form.photoReady;
 }
 function snapshot(){return {productId:product?.id||draft?.productId||null,fields:fieldsOf(form),photoSettings:settings,sources:Object.fromEntries(plan.inputs.filter(i=>sources[i.key]).map(i=>[i.key,sources[i.key]])),selected:{...selected}};}
 function save(){clearTimeout(timer);const data=snapshot();saveStatus.textContent='Сохраняем черновик…';saveChain=saveChain.catch(()=>{}).then(async()=>{const result=await draftRequest('/'+(draftId||'new'),data,'PUT');draftId=result.id;form.photoDraftId=draftId;saveStatus.textContent='Черновик сохранён';});saveChain.catch(e=>saveStatus.textContent=e.message);return saveChain;}
 form.flushPhotoDraft=save;form.clearPhotoDraft=async()=>{stopped=true;clearTimeout(timer);await saveChain.catch(()=>{});if(draftId)await draftRequest('/'+draftId,null,'DELETE');};
 form.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(save,350);});form.addEventListener('change',()=>{clearTimeout(timer);timer=setTimeout(save,100);});form.closest('dialog')?.addEventListener('close',()=>{if(!stopped)save();},{once:true});
 async function poll(row){const k=row.kind;if(!slotFor(k))return;busy.add(k);progress[k].start(sources[slotFor(k).source]||row.sourceImage);draw();try{for(let n=0;n<180&&alive();n++){const result=await request('/'+row.id);if(!alive())return;row.status=result.status;if(result.status==='failed'){progress[k].update('failed',result.message);return;}if(result.status==='completed'){if(compatible(row))selected[k]=row.id;progress[k].update('completed','Версия сохранена. Можно сравнить и выбрать другую.');await save();refreshPhotoCredits(creditOwner,true);return;}progress[k].update(result.stage||'processing');await new Promise(r=>setTimeout(r,2500));}}catch(e){progress[k].update('paused',e.message);status.textContent=e.message;}finally{busy.delete(k);progress[k].stop();draw();}}
 async function launch(k){const slot=slotFor(k);busy.add(k);progress[k].start(sources[slot.source]);draw();try{const result=await request('',{kind:k,draftId,image:sources[slot.source],category:category?.value||'Одежда',photoSettings:settings,audience:audience.value,modelGender:gender(),comment:host.querySelector(`[data-slot=${k}] [data-comment]`)?.value||''});let row=rows.find(r=>r.id===result.id);if(!row){row={id:result.id,kind:k,status:'processing',modelGender:gender(),recipeSignature:plan.signature,mode:slot.mode,sourceKey:slot.source};rows.push(row);}await poll(row);}catch(e){progress[k].update('failed',e.message);status.textContent=e.message;}finally{busy.delete(k);draw();}}
 async function refresh(){if(!draftId)return;const fresh=await draftRequest('/'+draftId);rows=[...new Map([...fresh.jobs,...(product?.photoStudio?.versions||[])].map(r=>[r.id,r])).values()];addPublished();for(const row of rows)if(row.status==='completed'&&compatible(row)&&!selected[row.kind]&&row.sourceImage===sources[slotFor(row.kind).source])selected[row.kind]=row.id;draw();await Promise.allSettled(rows.filter(r=>['starting','processing'].includes(r.status)&&compatible(r)&&!busy.has(r.kind)).map(poll));}
 function changeRecipe(){const old=plan,newPlan=photoPlan(category?.value||'Одежда',audience?.value,settings);if(old.signature!==newPlan.signature){selected={};if(old.settings.recipe!==newPlan.settings.recipe)sources={};}else if(form.photoModelGender!==gender())for(const s of newPlan.slots)if(['tryon','wear'].includes(s.mode))delete selected[s.key];layout();save();}
 host.addEventListener('change',async e=>{if(e.target.dataset.setting){settings={...settings,[e.target.dataset.setting]:e.target.dataset.setting==='extraCount'?Number(e.target.value):e.target.value};if(['childAge','childGender'].includes(e.target.dataset.setting)&&childTryonAllowed(category?.value))settings.shot='child';changeRecipe();return;}if(e.target.hasAttribute('data-model-choice')){modelChoice=e.target.value;changeRecipe();return;}const k=e.target.dataset.upload;if(k&&e.target.files[0]){busy.add(k);draw();status.textContent='Подготавливаем исходное фото…';try{const input=plan.inputs.find(i=>i.key===k);sources[k]=input.original?await readOriginal(e.target.files[0]):await preparePhoto(e.target.files[0]);for(const s of plan.slots)if(s.source===k)delete selected[s.key];await save();status.textContent='Исходник сохранён. Подготовка запускается по кнопке.';}catch(error){status.textContent=error.message;}finally{busy.delete(k);draw();}}});
 form.addEventListener('change',e=>{if(e.target===audience||e.target.matches('[data-category-parent],[data-category-child]'))changeRecipe();});
 host.addEventListener('click',async e=>{try{const zoom=e.target.closest('[data-zoom]');if(zoom){const viewer=document.createElement('dialog');viewer.className='photo-lightbox';viewer.innerHTML=`<button type="button" aria-label="Закрыть фото">×</button><img src="/api/photos/assets/${esc(zoom.dataset.zoom)}" alt="Фото в полном размере">`;document.body.append(viewer);viewer.querySelector('button').onclick=()=>viewer.close();viewer.addEventListener('close',()=>viewer.remove());viewer.showModal();return;}const select=e.target.closest('[data-select]');if(select){selected[select.dataset.kind]=select.dataset.select;draw();await save();return;}if(e.target.closest('[data-refresh]')){await refresh();return;}const redo=e.target.closest('[data-redo]');if((redo||e.target.closest('[data-generate-set]'))&&!busy.size&&(redo?ready(redo.dataset.redo):plan.slots.every(s=>ready(s.key)))){const kinds=redo?[redo.dataset.redo]:plan.slots.filter(s=>!selected[s.key]).map(s=>s.key);kinds.forEach(k=>busy.add(k));draw();try{await save();await Promise.allSettled(kinds.map(launch));}finally{kinds.forEach(k=>busy.delete(k));draw();}}}catch(error){status.textContent=error.message;}});
 function addPublished(){for(const [k,id] of Object.entries(product?.photoJobs||{}))if(!rows.some(r=>r.id===id))rows.push({id,kind:k,status:'completed',modelGender:product.modelGender||'female',recipeSignature:product.photoSettings?photoPlan(product.category,product.audience,product.photoSettings).signature:null});}
 addPublished();layout();await save();await refresh();
}
